module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

localparam IDLE = 2'b00;
localparam LOAD = 2'b01;
localparam CALCULATE = 2'b10;
localparam OUTPUT = 2'b11;

reg [1:0] state, next_state;
reg [3:0] mul_en_out_reg;
reg [7:0] mul_a_reg, mul_b_reg;
reg [15:0] temp [0:7];
reg [15:0] sum [0:3];
reg [15:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        mul_en_out_reg <= 4'd0;
        mul_a_reg <= 8'd0;
        mul_b_reg <= 8'd0;
        for (int i = 0; i < 8; i++) begin
            temp[i] <= 16'd0;
        end
        for (int i = 0; i < 4; i++) begin
            sum[i] <= 16'd0;
        end
        mul_out_reg <= 16'd0;
    end else begin
        state <= next_state;
        mul_en_out_reg <= {mul_en_out_reg[2:0], mul_en_in};
        if (mul_en_in) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end
        for (int i = 0; i < 8; i++) begin
            temp[i] <= (mul_b_reg[i] ? {8'd0, mul_a_reg} << i : 16'd0);
        end
        sum[0] <= temp[0] + temp[1];
        sum[1] <= temp[2] + temp[3];
        sum[2] <= temp[4] + temp[5];
        sum[3] <= temp[6] + temp[7];
        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
    end
end

always @* begin
    case(state)
        IDLE: begin
            if (mul_en_in) begin
                next_state = LOAD;
            end else begin
                next_state = IDLE;
            end
        end
        LOAD: begin
            if (mul_en_in) begin
                next_state = CALCULATE;
            end else begin
                next_state = IDLE;
            end
        end
        CALCULATE: begin
            if (mul_en_in) begin
                next_state = OUTPUT;
            end else begin
                next_state = IDLE;
            end
        end
        OUTPUT: begin
            if (mul_en_in) begin
                next_state = OUTPUT;
            end else begin
                next_state = IDLE;
            end
        end
        default: begin
            next_state = IDLE;
        end
    endcase
end

assign mul_en_out = mul_en_out_reg[3];
assign mul_out = mul_out_reg;
endmodule
